Your expense tracker is below. Add each spend with an amount and category, and the total and category split update as you go. Entries may not be kept once you close this page.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#fafaf7;color:#222}
h2{margin:0 0 4px}
.tot{font-size:28px;font-weight:700;margin:4px 0 12px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:8px;font-size:14px}
input{flex:1;min-width:90px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 8px}
.bar{height:10px;background:#2f7d5b;border-radius:5px}
.cat{margin:6px 0;font-size:13px}
.catrow{display:flex;justify-content:space-between}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
small{color:#777}
</style></head><body>
<h2>Monthly expenses</h2>
<div id="mon"><small></small></div>
<div class="tot" id="tot">₹0</div>
<div class="row">
<input id="note" placeholder="What for?">
<input id="amt" type="number" min="0" placeholder="Amount (₹)">
<select id="cat"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option></select>
<button onclick="add()">Add</button>
</div>
<div id="cats"></div>
<h3>Entries</h3>
<div id="list"></div>
<script>
var items=[];
try{items=JSON.parse(localStorage.getItem("exp")||"[]")}catch(e){}
function save(){try{localStorage.setItem("exp",JSON.stringify(items))}catch(e){}}
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function add(){
  var a=parseFloat(document.getElementById("amt").value);
  if(!(a>0))return;
  items.unshift({n:document.getElementById("note").value||"Expense",a:a,c:document.getElementById("cat").value});
  document.getElementById("amt").value="";document.getElementById("note").value="";
  save();draw();
}
function del(i){items.splice(i,1);save();draw()}
function draw(){
  var t=0,by={};
  items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a});
  document.getElementById("tot").textContent=inr(t);
  document.getElementById("mon").innerHTML="<small>"+new Date().toLocaleString("en-IN",{month:"long",year:"numeric"})+"</small>";
  var h="";
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    var p=Math.round(by[k]/t*100);
    h+='<div class="cat"><div class="catrow"><span>'+k+'</span><span>'+inr(by[k])+' ('+p+'%)</span></div><div class="bar" style="width:'+p+'%"></div></div>';
  });
  document.getElementById("cats").innerHTML=h;
  var l="";
  items.forEach(function(x,i){
    l+='<div class="item"><span>'+x.n.replace(/</g,"&lt;")+' <small>'+x.c+'</small></span><span>'+inr(x.a)+' <button class="x" onclick="del('+i+')">✕</button></span></div>';
  });
  document.getElementById("list").innerHTML=l||"<small>Nothing added yet.</small>";
}
draw();
</script></body></html>
```
